#include "../src/game.h"
#include "../src/match.h"
#include <cstdlib>
static int checks=0;static void check(bool value,const char* text){++checks;if(!value){printf("FAIL %s\n",text);exit(1);}}
int main(){g_world.build();auto& K=g_career;int a=-1,b=-1;for(auto& p:g_basePyramids)if(p.country=="FRA"&&p.dom<0)for(auto& pool:p.pools)if(pool.tier==0&&pool.clubs.size()>1){a=pool.clubs[0];b=pool.clubs[1];}check(a>=0&&b>=0,"club fixtures");K.opts=Career::Opts();K.newClubCareer(a,2026);g_world.ensureSquad(b);MatchSetup S;S.rules=RULESET_CAREER;S.home=a;S.away=b;supportersApplySetup(&K,S);check(S.personalityActive,"full career match activates personality");Match ordinary;auto base=S;base.personalityActive=false;ordinary.init(base);std::vector<int> before;for(auto& p:g_world.teams[a].squad)before.push_back(p.overall());Match live;live.init(S);for(int i=0;i<22;i++){const auto& p=live.pl[i];check(p.personalityStress>=.87f&&p.personalityStress<=1.13f,"live player stress bounded");check(p.personalityFoul>=.88f&&p.personalityFoul<=1.12f,"live player foul temperament bounded");check(p.personalityEngagement>=.95f&&p.personalityEngagement<=1.05f,"live engagement bounded");check(p.pass/ordinary.pl[i].pass>=.9549f&&p.pass/ordinary.pl[i].pass<=1.0401f,"actual starting-XI attribute variation bounded");}for(int i=0;i<(int)before.size();i++)check(before[i]==g_world.teams[a].squad[i].overall(),"match does not mutate technical level");auto practice=S;practice.training=true;supportersApplySetup(&K,practice);check(!practice.personalityActive,"training does not activate psychology");K.opts.lite=1;auto simple=S;simple.rules=RULESET_SIMPLE;supportersApplySetup(&K,simple);check(!simple.personalityActive,"simple match has no personality management");Match light;light.init(simple);for(auto& p:light.pl)check(p.personalityStress==1&&p.personalityFoul==1&&p.personalityEngagement==1,"simple live attributes retain default personality fields");printf("PASS build10 live match: %d checks\n",checks);}
